using System;
namespace HdrPilot {
public static partial class Guide {
 static Topic ReleaseNotes(){var rows=new[]{"1.0.8 · Revisione 2 (4 ottobre 2026). Corretto il controllo aggiornamenti RenoDX per i download GitHub Pages: confronto SHA256 con il file installato. Un file diverso viene proposto come aggiornamento, senza garantire che abbia una versione numericamente superiore. Il controllo non modifica i giochi. I problemi HTTP 5xx del server aggiornamenti ora invitano a riprovare più tardi; non indicano che la mod installata è guasta. Guida per principianti ampliata, rimosse istruzioni obsolete e chiarito quando compare Configura HDR. La configurazione HDR originale della 1.0.8 e il relativo ripristino restano disponibili.","1.0.8 · Revision 2 (4 October 2026). Fixed RenoDX update checks for GitHub Pages downloads using SHA256 comparison with the installed file. A different file is offered as an update, without claiming a higher version number. Checks do not change game files. HTTP 5xx update-server failures now ask you to retry later; they do not mean the installed mod is broken. Expanded beginner guide, removed obsolete instructions and clarified when Configure HDR appears. Original 1.0.8 HDR configuration and restoration remain available.","1.0.8 · Revisión 2 (4 octubre 2026). Corregida la búsqueda de actualizaciones RenoDX de GitHub Pages mediante SHA256. Un archivo distinto se ofrece como actualización, sin garantizar un número de versión superior. La comprobación no modifica juegos. Los errores HTTP 5xx invitan a reintentar; no indican una mod dañada. Guía ampliada, instrucciones obsoletas eliminadas y disponibilidad de Configurar HDR aclarada. Se conserva la configuración HDR y su restauración de 1.0.8.","1.0.8 · Révision 2 (4 octobre 2026). Correction des mises à jour RenoDX depuis GitHub Pages par comparaison SHA256. Un fichier différent est proposé sans garantir un numéro de version supérieur. La vérification ne modifie pas les jeux. Les erreurs HTTP 5xx invitent à réessayer et ne signalent pas un mod endommagé. Guide débutant enrichi, instructions obsolètes retirées et disponibilité de Configurer HDR précisée. La configuration HDR et sa restauration de 1.0.8 sont conservées.","1.0.8 · Revision 2 (4. Oktober 2026). RenoDX-Updateprüfung für GitHub Pages per SHA256-Vergleich korrigiert. Eine andere Datei wird angeboten, ohne eine höhere Versionsnummer zu garantieren. Prüfungen ändern keine Spieldateien. HTTP-5xx-Fehler fordern zum späteren Wiederholen auf und bedeuten keine defekte Mod. Einsteigerhilfe erweitert, veraltete Anweisungen entfernt und Verfügbarkeit von HDR konfigurieren erklärt. HDR-Konfiguration und Wiederherstellung aus 1.0.8 bleiben erhalten.","1.0.8 · Revisão 2 (4 outubro 2026). Corrigida a verificação RenoDX de GitHub Pages por SHA256. Um arquivo diferente é oferecido sem garantir uma versão superior. A verificação não altera jogos. Erros HTTP 5xx indicam tentar mais tarde, não uma mod danificada. Guia ampliado, instruções antigas removidas e disponibilidade de Configurar HDR esclarecida. Configuração HDR e restauro de 1.0.8 preservados."};int i=Array.IndexOf(new[]{"it","en","es","fr","de","pt"},Core.Pref.Language);return new Topic("Changelog · 1.0.8 r2",rows[i<0?1:i]);}
 static Topic[] NewTopics(){return new[]{
 ReleaseNotes(),
 RenoHdrHelp(),
 new Topic("MFG Unlock",Appearance.Localize(MfgAddon.Requirements),
 Appearance.Localize("Installation and updates"),Appearance.Localize("Install MFG Unlock checks the latest stable release from nefh/MFGAmpereUnlock-RenoDx, verifies its SHA256 and configures early loading in ReShade.ini. Other add-ons and their settings are preserved. Update MFG Unlock checks online again; a failed check never installs an old cached package."),
 Appearance.Localize("Runtime requirements"),Appearance.Localize("The author currently specifies DLSS-G 310.9.1 for the full feature set. Dynamic MFG requires a qualified Direct3D 12 / Streamline 2.14.1 path and driver 595.41 or newer. Do not replace legacy Streamline 1.x with 2.x. HDLSS leaves NVIDIA and Streamline files intact; consult MFG Unlock compatibility for the selected game."),
 Appearance.Localize("Removal"),Appearance.Localize("In the main game page, use the individual removal buttons. Mod updates and Check again are on the same page. Other components remain on disk.")),
 new Topic("HTTP 403 / GitHub",Appearance.Localize("Stable ReShade is downloaded from reshade.me without GitHub API requests. RenoDX GitHub Pages downloads are compared by SHA256 with the installed add-on; a different file is offered as an update, not proof of a newer version. Checks do not change game files. GitHub metadata is cached for 30 minutes; rate limits pause requests until the server reset time. Failed checks never mean up to date. A crash still requires a separate game and add-on diagnosis.")),
 new Topic("ReShade / RenoDX",Appearance.Localize("Stable ReShade uses the latest official full add-on package; nightly uses the latest successful development build. RenoDX is matched against the current game catalog and checks recent published assets. Unsupported or ambiguous packages stop the installation. Local imports use the file you select and cannot certify that it is the latest release."),
 Appearance.Localize("Separate components"),Appearance.Localize("MFG Unlock is separate from HDR RenoDX and OptiScaler Frame Generation. Installed files are not proof of activation. Check the ReShade log and the MFG Unlock panel in the running game. MFG Unlock does not add native DLSS FG to a game that lacks it.")),
 new Topic("DLL / Streamline / Neural Rendering",Appearance.Localize("The catalog is bundled and refreshed online. If the network is unavailable, local choices remain. Files download when you install; verified cached DLSS DLLs can be reused. Select a path when the game has multiple copies. Installation, backup and errors stay on the page. Nexus still requires the website download; Import opens the Windows file picker.")),
 new Topic("DLSS / OptiScaler",Appearance.Localize("The DLSS section uses vertical groups: Neural Rendering, Frame Generation, DLSS components and Customize. Buttons retain their original style. Install OptiScaler and Apply settings remain visible at the bottom; scroll to reach details and recovery tools.")),
 new Topic(Appearance.Localize("Manual add-on"),Appearance.Localize("Manual add-ons are listed separately from managed RenoDX HDR. Each has its own removal button. Nexus updates require the website download; unknown sources use Import update. Only the matching add-on is replaced, with backup.")),
 new Topic(Appearance.Localize("Add-on e shader ReShade"),Appearance.Localize("Select a package, then Install selected or Remove selected. Yellow means installed, not update available. Updates are listed separately.")),
 new Topic("ASI Loader",Appearance.Localize(AsiLoader.Help)),
 new Topic(Appearance.Localize("Removal"),Appearance.Localize("Remove one component at a time. Files are deleted with a recovery copy; other mods are preserved.")),
 new Topic(Appearance.Localize("Mod updates"),Appearance.Localize("Checks run at startup. Updates are applied only when you choose them, with backup.")+"\n"+Appearance.Localize("Unrecognized versions are reported as unknown, never as up to date. Corrupt metadata is fetched again. Updates wait for the server retry time; duplicate target paths are rejected before files are changed.")),
 new Topic(Appearance.Localize("Clean duplicate loaders"),Appearance.Localize("Only byte-identical mod loaders in this folder are removed. One loader imported by the game is kept; native DLL copies in other folders are preserved.")+"\n"+Appearance.Localize("Loaders explicitly imported by the game are preserved, even when their files are identical.")),
 new Topic("Streamline",Appearance.Localize(Streamline.Help)),
 new Topic("UE4SS",Appearance.Localize("Install UE4SS for mods downloads the latest official stable runtime for a supported Unreal game, without the HDLSS telemetry reader. Existing UE4SS and mods are preserved. Check compatibility with the game and its mods before changing a runtime.")),
 new Topic(Appearance.Localize("Backups and updates"),Appearance.Localize("Checks run at startup. Updates are applied only when you choose them, with backup.")+"\n"+Appearance.Localize("Files updated and verified. Launch the game to verify compatibility and activation."))
 };}
 static Topic RenoHdrHelp(){string[][] rows=new[]{
new[]{"Configura HDR · RenoDX","Configura HDR compare solo per i giochi riconosciuti dall’app che richiedono una configurazione aggiuntiva per RenoDX. Si abilita dopo il rilevamento della mod richiesta. Se non compare, salta questo passaggio e segui le istruzioni della mod: l’assenza non garantisce la compatibilità automatica. The Blood of Dawnwalker è un esempio di profilo incluso.","1. Prima di iniziare","Attiva HDR nelle impostazioni di Windows. Avvia il gioco almeno una volta, poi chiudilo. In HDLSS seleziona il gioco e apri HDR / MFG. Installa ReShade e RenoDX Unreal Engine Extended.","2. Configura il gioco","Premi Configura HDR. HDLSS salva una copia delle impostazioni, prepara Engine.ini e abilita l’aggiornamento dei cursori RenoDX. Attendi il completamento. Non occorre aggiungere manualmente queste righe al file.","3. Verifica in gioco","Riavvia il gioco e carica una partita. Apri ReShade con il tasto configurato (Home, se non lo hai cambiato), poi il pannello RenoDX. Prova a variare Exposure e riportalo al valore precedente. Se l’immagine reagisce, il controllo sta agendo. Regola picco e luminosità nel pannello RenoDX. HDR configurato in giallo conferma le impostazioni nei file: non è una misura dei nit e non certifica la resa del monitor.","4. Ripristino e problemi","Ripristina configurazione HDR annulla le sole impostazioni gestite dall’app rimaste invariate. Rimuovi RenoDX rimuove anche la configurazione gestita. Le modifiche successive e le impostazioni preesistenti non gestite sono conservate. Se il pulsante è disabilitato, installa prima RenoDX; se manca, il gioco non ha un profilo supportato. Se i cursori non agiscono, verifica il log ReShade e la compatibilità della mod con la versione del gioco. I profili sono inclusi nell’app: non vengono aggiornati online.","5. Cosa cambia e cosa significa il giallo","Nel profilo Dawnwalker l’app crea o aggiorna Engine.ini nella cartella locale del gioco, imposta il percorso HDR10 e l’aggiornamento dei controlli RenoDX e protegge il file in sola lettura. Aggiorna anche il percorso HDR in ReShade.ini. GameUserSettings.ini deve esistere dopo il primo avvio, ma non viene modificato. Il comando non installa la mod, non abilita HDR in Windows e non imposta né misura il picco del monitor. HDR configurato significa che i valori nei file sono corretti, anche se già presenti prima. Ripristina configurazione HDR compare solo se HDLSS ha registrato una propria modifica con backup; le impostazioni manuali preesistenti non hanno un ripristino automatico."},
new[]{"Configure HDR · RenoDX","Configure HDR appears only for recognized games that require additional RenoDX configuration. It becomes available after the required mod is detected. If absent, skip this step and follow the mod instructions: absence does not guarantee automatic compatibility. The Blood of Dawnwalker is an example of a bundled profile.","1. Before you start","Enable HDR in Windows. Run the game at least once, then close it. Select the game in HDLSS and open HDR / MFG. Install ReShade and RenoDX Unreal Engine Extended.","2. Configure the game","Press Configure HDR. HDLSS backs up settings, prepares Engine.ini and enables live RenoDX slider updates. Wait for completion. You do not need to add these lines manually.","3. Check in game","Restart and load a save. Open ReShade with your configured key (Home unless changed), then RenoDX. Change Exposure briefly and restore its previous value. A visible response shows that control is acting. Adjust peak and brightness in RenoDX. Yellow HDR configured confirms file settings; it does not measure nits or certify monitor output.","4. Restore and troubleshoot","Restore HDR configuration reverts only unchanged values managed by the app. Remove RenoDX also removes its managed configuration. Later edits and unmanaged existing settings are preserved. If the button is disabled, install RenoDX first; if absent, the game has no supported profile. If sliders do nothing, check the ReShade log and mod compatibility with your game version. Profiles ship with the app and are not refreshed online.","5. Files and yellow status","For Dawnwalker, HDLSS creates or updates Engine.ini, selects HDR10 and live RenoDX controls, and makes the file read-only. It also sets the HDR path in ReShade.ini. GameUserSettings.ini must exist after the first launch but is not edited. This does not install the mod, enable Windows HDR or set or measure monitor peak brightness. HDR configured confirms file values, including pre-existing ones. Restore HDR configuration appears only when HDLSS recorded its own change with backup; pre-existing manual settings have no automatic restore."},
new[]{"Configurar HDR · RenoDX","Configurar HDR aparece solo para juegos reconocidos que necesitan configuración adicional para RenoDX. Se habilita al detectar la mod requerida. Si no aparece, omite este paso y sigue las instrucciones de la mod; su ausencia no garantiza compatibilidad automática. The Blood of Dawnwalker es un ejemplo de perfil incluido.","1. Preparación","Activa HDR en Windows. Inicia el juego una vez y ciérralo. Selecciona el juego en HDLSS, abre HDR / MFG e instala ReShade y RenoDX Unreal Engine Extended.","2. Configuración","Pulsa Configurar HDR. HDLSS guarda una copia, prepara Engine.ini y activa los cambios en tiempo real de RenoDX. Espera a que termine; no añadas las líneas manualmente.","3. Comprobación","Reinicia y carga una partida. Abre ReShade con la tecla configurada (Home por defecto) y después RenoDX. Cambia Exposure brevemente y restablece su valor. Una respuesta visible indica que el control actúa. Ajusta brillo y pico en RenoDX. HDR configurado en amarillo confirma archivos; no mide nits ni verifica el monitor.","4. Restauración y problemas","Restaurar configuración HDR revierte solo valores gestionados sin cambios posteriores. Quitar RenoDX también retira su configuración gestionada. Se conservan cambios posteriores y ajustes previos no gestionados. Si el botón está desactivado, instala RenoDX; si no aparece, no hay perfil compatible. Si los controles no actúan, revisa el registro ReShade y la compatibilidad con tu versión del juego. Los perfiles vienen con la app y no se actualizan en línea.","5. Archivos y estado amarillo","En Dawnwalker se crea o actualiza Engine.ini con HDR10 y controles RenoDX en tiempo real, en solo lectura, y la ruta HDR de ReShade.ini. GameUserSettings.ini debe existir, pero no se modifica. No instala la mod, activa HDR de Windows ni ajusta o mide el pico del monitor. HDR configurado confirma valores, incluso previos. Restaurar solo aparece si HDLSS registró su propio cambio con copia; los ajustes manuales previos no tienen restauración automática."},
new[]{"Configurer HDR · RenoDX","Configurer HDR apparaît uniquement pour les jeux reconnus nécessitant une configuration supplémentaire pour RenoDX. Le bouton devient disponible après détection du mod requis. Sinon, passez cette étape et suivez les instructions du mod ; son absence ne garantit pas la compatibilité automatique. The Blood of Dawnwalker est un exemple de profil inclus.","1. Préparation","Activez HDR dans Windows. Lancez le jeu une fois, puis fermez-le. Sélectionnez-le dans HDLSS, ouvrez HDR / MFG et installez ReShade et RenoDX Unreal Engine Extended.","2. Configuration","Cliquez sur Configurer HDR. HDLSS sauvegarde les réglages, prépare Engine.ini et active les curseurs RenoDX en temps réel. Attendez la fin ; inutile d’ajouter les lignes manuellement.","3. Vérification en jeu","Redémarrez et chargez une partie. Ouvrez ReShade avec la touche configurée (Home par défaut), puis RenoDX. Modifiez brièvement Exposure et rétablissez sa valeur. Une réaction visible indique que ce réglage agit. Réglez le pic et la luminosité dans RenoDX. HDR configuré en jaune confirme les fichiers, sans mesurer les nits ni certifier le moniteur.","4. Restauration et dépannage","Restaurer la configuration HDR rétablit uniquement les valeurs gérées inchangées. Retirer RenoDX retire aussi sa configuration gérée. Les modifications ultérieures et les réglages préexistants non gérés sont conservés. Si le bouton est désactivé, installez RenoDX ; s’il est absent, aucun profil compatible n’existe. Sans réaction des curseurs, vérifiez le journal ReShade et la compatibilité avec la version du jeu. Les profils sont inclus dans l’app et ne sont pas actualisés en ligne.","5. Fichiers et état jaune","Pour Dawnwalker, Engine.ini est créé ou modifié pour HDR10 et les contrôles RenoDX en temps réel, puis placé en lecture seule. Le chemin HDR de ReShade.ini est réglé. GameUserSettings.ini doit exister mais reste inchangé. Cela n’installe pas le mod, n’active pas HDR dans Windows et ne règle ni ne mesure le pic du moniteur. HDR configuré confirme les valeurs, même préexistantes. La restauration apparaît uniquement après une modification sauvegardée par HDLSS ; les réglages manuels antérieurs ne sont pas restaurés automatiquement."},
new[]{"HDR konfigurieren · RenoDX","HDR konfigurieren erscheint nur bei erkannten Spielen, die zusätzliche RenoDX-Einstellungen benötigen. Die Funktion wird nach Erkennung der erforderlichen Mod verfügbar. Fehlt sie, überspringe diesen Schritt und befolge die Mod-Anleitung; das garantiert keine automatische Kompatibilität. The Blood of Dawnwalker ist ein Beispiel für ein enthaltenes Profil.","1. Vorbereitung","Aktiviere HDR in Windows. Starte das Spiel einmal und schließe es. Wähle es in HDLSS, öffne HDR / MFG und installiere ReShade sowie RenoDX Unreal Engine Extended.","2. Einrichtung","Klicke auf HDR konfigurieren. HDLSS sichert Einstellungen, richtet Engine.ini ein und aktiviert sofortige RenoDX-Regleränderungen. Warte auf den Abschluss. Manuelle INI-Einträge sind nicht nötig.","3. Im Spiel prüfen","Starte neu und lade einen Spielstand. Öffne ReShade mit der eingestellten Taste (standardmäßig Home), dann RenoDX. Ändere kurz Exposure und stelle den alten Wert wieder her. Eine sichtbare Änderung zeigt, dass dieser Regler wirkt. Spitzenhelligkeit und Helligkeit stellst du in RenoDX ein. HDR konfiguriert in Gelb bestätigt Dateien, keine Nit-Messung oder geprüfte Monitorausgabe.","4. Wiederherstellung und Probleme","HDR-Konfiguration wiederherstellen setzt nur unveränderte verwaltete Werte zurück. RenoDX entfernen entfernt auch seine verwaltete Konfiguration. Spätere Änderungen und nicht verwaltete vorhandene Werte bleiben erhalten. Bei deaktiviertem Button installiere RenoDX; fehlt er, gibt es kein unterstütztes Profil. Reagieren Regler nicht, prüfe ReShade-Protokoll und Kompatibilität mit der Spielversion. Profile werden mitgeliefert und nicht online aktualisiert.","5. Dateien und gelber Status","Für Dawnwalker erstellt oder ändert HDLSS Engine.ini für HDR10 und direkte RenoDX-Regleränderungen und setzt Schreibschutz sowie den HDR-Pfad in ReShade.ini. GameUserSettings.ini muss existieren, wird aber nicht geändert. Die Funktion installiert keine Mod, aktiviert kein Windows-HDR und setzt oder misst keine Spitzenhelligkeit. HDR konfiguriert bestätigt auch bereits vorhandene Werte. Wiederherstellen erscheint nur nach einer von HDLSS gesicherten Änderung; frühere manuelle Einstellungen haben keine automatische Wiederherstellung."},
new[]{"Configurar HDR · RenoDX","Configurar HDR aparece apenas em jogos reconhecidos que precisam de configuração adicional para RenoDX. Fica disponível após detectar a mod necessária. Se não aparecer, ignore este passo e siga as instruções da mod; a ausência não garante compatibilidade automática. The Blood of Dawnwalker é um exemplo de perfil incluído.","1. Preparação","Ative HDR no Windows. Inicie o jogo uma vez e feche-o. Selecione-o no HDLSS, abra HDR / MFG e instale ReShade e RenoDX Unreal Engine Extended.","2. Configuração","Prima Configurar HDR. HDLSS cria um backup, prepara Engine.ini e ativa os controles RenoDX em tempo real. Aguarde a conclusão; não é necessário adicionar as linhas manualmente.","3. Verificação no jogo","Reinicie e carregue uma partida. Abra ReShade com a tecla configurada (Home por padrão), depois RenoDX. Altere Exposure brevemente e reponha o valor anterior. Uma resposta visível indica que esse controle atua. Ajuste pico e brilho no RenoDX. HDR configurado em amarelo confirma arquivos; não mede nits nem verifica a saída do monitor.","4. Restauro e problemas","Restaurar configuração HDR repõe apenas valores geridos sem alterações posteriores. Remover RenoDX também remove a configuração gerida. Alterações posteriores e ajustes existentes não geridos são preservados. Se o botão estiver desativado, instale RenoDX; se ausente, não existe perfil suportado. Se os controles não reagirem, verifique o log ReShade e a compatibilidade com a versão do jogo. Os perfis vêm com a app e não são atualizados online.","5. Arquivos e estado amarelo","Para Dawnwalker, cria ou atualiza Engine.ini para HDR10 e controles RenoDX em tempo real, define somente leitura e o caminho HDR de ReShade.ini. GameUserSettings.ini deve existir, mas não é alterado. Não instala a mod, ativa HDR do Windows nem define ou mede o pico do monitor. HDR configurado confirma valores, incluindo os preexistentes. Restaurar aparece apenas após uma alteração própria com backup; configurações manuais anteriores não têm restauro automático."}
};int i=Array.IndexOf(new[]{"it","en","es","fr","de","pt"},Core.Pref.Language);var r=rows[i<0?1:i];var sections=new string[r.Length-2];Array.Copy(r,2,sections,0,sections.Length);return new Topic(r[0],r[1],sections);}

}
}
